const jsondata = {
 "apiClassName": "PointCloudSimAPI",
 "apiFuncName": "CreatePointCloudSim",
 "args":
 {
  "guid": "", //可以不用去填，空着即可
  "data": [], //data里是对应各监测点位的pos（cad中的偏移量），以及各监测点的values，values里面可以填单时序的数据，也可以是多时序的数组
  "pointSimName": "zoumazhuang", // 唯一名字，用户可以自己定义
  "currentValueIndex": 0, // 当前显示的时序帧index，需要注意：第一帧的index需从0开始
  "coordinate": "CAD", // 坐标系Local/Gis/CAD，密云项目中填入"CAD"
  "dataValueRange": [ 0, 0 ], //色卡的阈值范围，最小值~最大值
  "pointSize": 1, //点云点大小控制
  "sourceCRS": "", // GIS坐标转换，原始坐标系，需填入本项目中所使用的坐标系，，密云项目的话，就填入"EPSG:4326"
  "targetCRS": "", // GIS坐标转换，投影坐标系，需填入本项目中所使用的坐标系转换规则，密云项目的话，就填入"+proj=ortho +lon_0=116.83241904356427 +lat_0=40.48456289244539 +a=6371010 +units=m +no_defs"
  "cadOrigin": [ 0, 0, 0 ], // cad坐标原点所对应的GIS坐标
  "bLoopValue": false, //是否循环播放
  "tickValueTime": 1 // 循环播放切换时间间隔（s）
 }
};
const res = await App.Customize.RunCustomizeApi(jsondata);
console.log(res);

